use knownext_storage::LocalApi;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf};
fn setup()->(tempfile::TempDir,LocalApi,String,String,PathBuf,Value){let temp=tempfile::tempdir().unwrap();let api=LocalApi::new(temp.path().join("state"),"qa".into(),"test".into());let project=api.handle("POST","/api/projects",json!({"name":"Owned future source","versioningMode":"none","syncMode":"none"}),vec![]).unwrap().body;let owner=project["id"].as_str().unwrap().to_string();let created=api.handle("POST",&format!("/api/projects/{owner}/handwritten-notes"),json!({"name":"Owned.knote"}),vec![]).unwrap().body;let id=created["node"]["id"].as_str().unwrap().to_string();let record=api.handle("GET",&format!("/api/handwritten-notes/{id}"),Value::Null,vec![]).unwrap().body;let path=PathBuf::from(project["folderPath"].as_str().unwrap()).join("Owned.knote");(temp,api,owner,id,path,record)}
#[test]
fn incompatible_source_is_never_downgraded_even_with_force_and_known_local_draft_can_be_recovered_separately(){
    let(temp,api,owner,id,path,record)=setup();let route=format!("/api/handwritten-notes/{id}");let mut future=record["content"].clone();future["schemaVersion"]=json!(99);let future=serde_json::to_vec_pretty(&future).unwrap();fs::write(&path,&future).unwrap();assert!(api.handle("GET",&route,Value::Null,vec![]).is_err());assert!(api.handle("PUT",&route,json!({"force":true,"content":record["content"]}),vec![]).is_err());assert_eq!(fs::read(&path).unwrap(),future);
    let mut local=record["content"].clone();local["title"]=json!("Known local work");let saved=api.handle("PUT",&format!("{route}/draft"),json!({"content":local,"baseFingerprint":record["baseFingerprint"]}),vec![]).unwrap().body;assert!(saved["sourceWarning"].is_string());let reopened=LocalApi::new(temp.path().join("state"),"qa".into(),"test".into());let observed=reopened.handle("GET",&route,Value::Null,vec![]).unwrap().body;assert_eq!(observed["content"]["title"],"Known local work");assert_eq!(observed["sourceUnavailable"],true);assert_eq!(observed["hasDraft"],true);assert!(observed["diskContent"].is_null());assert_eq!(fs::read(&path).unwrap(),future);
    let draft=temp.path().join("state/drafts").join(format!("v2_{:x}.json",Sha256::digest(id.as_bytes())));let original_draft=fs::read(&draft).unwrap();assert!(reopened.handle("POST",&format!("{route}/draft/discard-and-read"),json!({"expectedDraftWriteRevision":observed["draftWriteRevision"]}),vec![]).is_err());assert!(reopened.handle("PUT",&route,json!({"force":true,"content":local,"expectedDraftWriteRevision":observed["draftWriteRevision"]}),vec![]).is_err());assert_eq!(fs::read(&draft).unwrap(),original_draft);
    let review=reopened.handle("GET","/api/recovery/drafts",Value::Null,vec![]).unwrap().body;let item=review["items"].as_array().unwrap().iter().find(|v|v["documentId"]==id).unwrap();assert_eq!(item["canCopy"],true);let copied=reopened.handle("POST",&format!("/api/recovery/drafts/{}/copy",item["key"].as_str().unwrap()),json!({"fingerprint":item["fingerprint"],"projectId":owner,"name":"Recovered.knote"}),vec![]).unwrap().body;assert_eq!(copied["note"]["content"]["title"],"Known local work");assert_eq!(fs::read(&draft).unwrap(),original_draft);assert_eq!(fs::read(&path).unwrap(),future);
}
#[test]
fn future_payloads_and_future_draft_contents_remain_intact_and_missing_source_can_be_recreated_explicitly(){
    let(temp,api,_owner,id,path,record)=setup();let route=format!("/api/handwritten-notes/{id}");let original=fs::read(&path).unwrap();let mut future=record["content"].clone();future["schemaVersion"]=json!(99);for suffix in ["","/draft"]{assert!(api.handle("PUT",&format!("{route}{suffix}"),json!({"force":true,"content":future}),vec![]).is_err());assert_eq!(fs::read(&path).unwrap(),original);}
    let draft=temp.path().join("state/drafts").join(format!("v2_{:x}.json",Sha256::digest(id.as_bytes())));fs::create_dir_all(draft.parent().unwrap()).unwrap();let value=serde_json::to_vec(&json!({"documentId":id,"content":future})).unwrap();fs::write(&draft,&value).unwrap();assert!(api.handle("GET",&route,Value::Null,vec![]).is_err());let blocked=api.handle("PUT",&route,json!({"force":true,"content":record["content"]}),vec![]).unwrap();assert_eq!(blocked.status,503);assert_eq!(blocked.body["operationOutcome"],"not-started");assert_eq!(fs::read(&draft).unwrap(),value);let review=api.handle("GET","/api/recovery/drafts",Value::Null,vec![]).unwrap().body;assert_eq!(review["items"][0]["canCopy"],false);
    fs::remove_file(&draft).unwrap();fs::remove_file(&path).unwrap();let saved=api.handle("PUT",&route,json!({"force":true,"content":record["content"]}),vec![]).unwrap().body;assert_eq!(saved["content"]["pages"],record["content"]["pages"]);assert_eq!(saved["hasDraft"],false);assert!(path.is_file());
    let file=fs::File::create(&path).unwrap();file.set_len(64*1024*1024+1).unwrap();drop(file);assert!(api.handle("PUT",&route,json!({"force":true,"content":record["content"]}),vec![]).is_err());assert_eq!(fs::metadata(&path).unwrap().len(),64*1024*1024+1);
}

#[test]
fn incompatible_known_fields_and_future_pencil_textures_are_not_silently_normalized(){
    let(_temp,api,_owner,id,path,record)=setup();let route=format!("/api/handwritten-notes/{id}");
    let mut texture=record["content"].clone();texture["pages"][0]["strokes"]=json!([{"id":"owned-future-ink","tool":"pencil","textureVersion":2,"textureSeed":"owned","color":"#111827","width":2,"opacity":1,"points":[[10,20,0.7,0,45,-30]]}]);
    let mut ocr=record["content"].clone();ocr["ocr"]["textByPage"]=json!(["owned future structure"]);let mut unit=record["content"].clone();unit["pages"][0]["size"]["unit"]=json!("mm");
    let mut duplicate=record["content"].clone();duplicate["pages"].as_array_mut().unwrap().push(record["content"]["pages"][0].clone());
    for source in [texture,ocr,unit,duplicate]{let bytes=serde_json::to_vec_pretty(&source).unwrap();fs::write(&path,&bytes).unwrap();assert!(api.handle("GET",&route,Value::Null,vec![]).is_err());assert!(api.handle("PUT",&route,json!({"force":true,"content":record["content"]}),vec![]).is_err());assert_eq!(fs::read(&path).unwrap(),bytes);}
}
